import math
def incr(vals):
    m=0.0; n=0; ss=0.0
    for v in vals:
        n+=1
        m += (v-m)/n
        ss += v*v
    return m, math.sqrt(ss/n - m*m) if n else None
def welford(vals):
    m=0.0; s=0.0; n=0
    for v in vals:
        n+=1
        d = v-m
        m += d/n
        s += d*(v-m)
