//! A minimal re-implementation of the pieces of a CSV reader/writer that this
//! program relies upon.  The reader is byte oriented and reproduces the record
//! position accounting used by the original program (which includes a quirk in
//! how `\r\n` terminated records update the line/byte counters).
use std::io::{self, Read, Write};

#[derive(Clone, Copy, Debug)]
pub struct Position {
    pub record: u64,
    pub line: u64,
    pub byte: u64,
}

#[derive(Clone, Debug)]
pub struct CsvError {
    pub kind: ErrKind,
    pub pos: Option<Position>,
}

#[derive(Clone, Debug)]
pub enum ErrKind {
    Io(String),
    UnequalLengths { expected: u64, len: u64 },
    Utf8,
}

impl std::fmt::Display for CsvError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self.kind {
            ErrKind::Io(ref m) => write!(f, "{}", m),
            ErrKind::UnequalLengths { expected, len } => match self.pos {
                Some(p) => write!(
                    f,
                    "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                    p.record, p.line, p.byte, len, expected
                ),
                None => write!(
                    f,
                    "CSV error: found record with {} fields, but the previous record has {} fields",
                    len, expected
                ),
            },
            ErrKind::Utf8 => write!(f, "CSV error: invalid UTF-8"),
        }
    }
}

pub type CsvResult<T> = Result<T, CsvError>;

fn io_err(e: &io::Error) -> CsvError {
    CsvError { kind: ErrKind::Io(e.to_string()), pos: None }
}

pub struct Reader<R> {
    rdr: R,
    buf: Vec<u8>,
    start: usize,
    end: usize,
    eof: bool,
    pub delimiter: u8,
    pub quote: u8,
    pub escape: Option<u8>,
    pub quoting: bool,
    pub flexible: bool,
    pub line: u64,
    pub byte: u64,
    pub record: u64,
    pending_nl: bool,
    expected: Option<usize>,
}

impl<R: Read> Reader<R> {
    pub fn new(rdr: R) -> Reader<R> {
        Reader {
            rdr,
            buf: vec![0; 8 * (1 << 10)],
            start: 0,
            end: 0,
            eof: false,
            delimiter: b',',
            quote: b'"',
            escape: None,
            quoting: true,
            flexible: false,
            line: 1,
            byte: 0,
            record: 0,
            pending_nl: false,
            expected: None,
        }
    }

    #[inline]
    fn avail(&self) -> usize {
        self.end - self.start
    }

    /// Make sure at least one byte is buffered. Returns false at EOF.
    fn fill(&mut self) -> CsvResult<bool> {
        if self.start < self.end {
            return Ok(true);
        }
        if self.eof {
            return Ok(false);
        }
        loop {
            if self.start > 0 {
                self.buf.copy_within(self.start..self.end, 0);
                self.end -= self.start;
                self.start = 0;
            }
            if self.end == self.buf.len() {
                self.buf.resize(self.buf.len() * 2, 0);
            }
            let n = self.rdr.read(&mut self.buf[self.end..]).map_err(|e| io_err(&e))?;
            if n == 0 {
                self.eof = true;
                return Ok(self.start < self.end);
            }
            self.end += n;
            return Ok(true);
        }
    }

    fn peek(&mut self) -> CsvResult<Option<u8>> {
        if self.fill()? {
            Ok(Some(self.buf[self.start]))
        } else {
            Ok(None)
        }
    }

    fn bump(&mut self) {
        self.start += 1;
        self.byte += 1;
    }

    /// Returns the next byte without consuming, or None at EOF.
    fn la(&mut self) -> CsvResult<Option<u8>> {
        self.peek()
    }

    fn is_term(&self, b: u8) -> bool {
        b == b'\n' || b == b'\r'
    }

    /// Read one field, stopping at the delimiter or a record terminator.
    fn read_field(&mut self, out: &mut Vec<u8>) -> CsvResult<()> {
        out.clear();
        if self.quoting {
            if let Some(q) = self.la()? {
                if q == self.quote {
                    self.bump();
                    self.read_quoted(out)?;
                    // After a quoted field, anything up to the next delimiter or
                    // record terminator is appended to the same field.
                    self.read_unquoted_tail(out)?;
                    return Ok(());
                }
            }
        }
        self.read_unquoted(out)?;
        Ok(())
    }

    fn read_quoted(&mut self, out: &mut Vec<u8>) -> CsvResult<()> {
        loop {
            match self.la()? {
                None => return Ok(()),
                Some(b) => {
                    if b == self.quote {
                        self.bump();
                        // Escaped quote (doubled) or the end of the quoted region.
                        if self.la()? == Some(self.quote) {
                            self.bump();
                            out.push(self.quote);
                            continue;
                        }
                        return Ok(());
                    } else if self.escape == Some(b) {
                        self.bump();
                        // The escape character escapes the next character.
                        match self.la()? {
                            None => return Ok(()),
                            Some(c) => {
                                self.bump();
                                out.push(c);
                            }
                        }
                        continue;
                    } else {
                        self.bump();
                        out.push(b);
                    }
                }
            }
        }
    }

    fn read_unquoted(&mut self, out: &mut Vec<u8>) -> CsvResult<()> {
        loop {
            match self.la()? {
                None => return Ok(()),
                Some(b) => {
                    if b == self.delimiter || self.is_term(b) {
                        return Ok(());
                    }
                    self.bump();
                    out.push(b);
                }
            }
        }
    }

    fn read_unquoted_tail(&mut self, out: &mut Vec<u8>) -> CsvResult<()> {
        loop {
            match self.la()? {
                None => return Ok(()),
                Some(b) => {
                    if b == self.delimiter || self.is_term(b) {
                        return Ok(());
                    }
                    self.bump();
                    out.push(b);
                }
            }
        }
    }

    /// Read a single record. Returns Ok(true) if a record was read, Ok(false)
    /// at EOF. Blank records (a lone record terminator) are skipped.
    pub fn read(&mut self, out: &mut Vec<Vec<u8>>) -> CsvResult<bool> {
        loop {
            let snap = Position { record: self.record, line: self.line, byte: self.byte };
            if self.pending_nl {
                self.pending_nl = false;
                self.byte += 1;
                self.line += 1;
            }
            if self.la()?.is_none() {
                return Ok(false);
            }
            out.clear();
            let mut fields = 0usize;
            loop {
                let mut field = Vec::with_capacity(16);
                self.read_field(&mut field)?;
                out.push(field);
                fields += 1;
                match self.la()? {
                    None => break,
                    Some(d) if d == self.delimiter => {
                        self.bump();
                        continue;
                    }
                    Some(b'\n') => {
                        self.bump();
                        self.line += 1;
                        break;
                    }
                    Some(b'\r') => {
                        self.bump();
                        if self.la()? == Some(b'\n') {
                            self.bump();
                            self.pending_nl = true;
                        }
                        break;
                    }
                    Some(_) => break,
                }
            }
            if fields == 1 && out[0].is_empty() && !self.eof_after_record() {
                // A blank line: skip it.
                continue;
            }
            if fields == 1 && out[0].is_empty() && self.eof {
                // Trailing record with no content and no terminator: not a record.
                return Ok(false);
            }
            if !self.flexible {
                if let Some(exp) = self.expected {
                    if exp != fields {
                        return Err(CsvError {
                            kind: ErrKind::UnequalLengths { expected: exp as u64, len: fields as u64 },
                            pos: Some(snap),
                        });
                    }
                }
            }
            self.expected = Some(fields);
            self.record += 1;
            return Ok(true);
        }
    }

    fn eof_after_record(&self) -> bool {
        self.eof && self.start >= self.end
    }
}

/// A CSV writer with quoting rules matching the original program.
pub struct Writer<W> {
    wtr: W,
    pub delimiter: u8,
    pub quote: u8,
    pub escape: Option<u8>,
    pub double_quote: bool,
    pub quoting: bool,
    pub term: Vec<u8>,
}

impl<W: Write> Writer<W> {
    pub fn new(wtr: W) -> Writer<W> {
        Writer {
            wtr,
            delimiter: b',',
            quote: b'"',
            escape: None,
            double_quote: true,
            quoting: true,
            term: vec![b'\n'],
        }
    }

    fn needs_quotes(&self, field: &[u8]) -> bool {
        for &b in field.iter() {
            if b == self.delimiter || b == self.quote || b == b'\r' || b == b'\n' {
                return true;
            }
        }
        false
    }

    fn write_field(&mut self, field: &[u8], quoted: bool) -> io::Result<()> {
        if !self.quoting {
            self.wtr.write_all(field)?;
            return Ok(());
        }
        let needs = quoted || self.needs_quotes(field);
        if needs {
            self.wtr.write_all(&[self.quote])?;
        }
        if needs && field.contains(&self.quote) {
            if let Some(esc) = self.escape {
                let mut i = 0;
                while i < field.len() {
                    if field[i] == self.quote {
                        self.wtr.write_all(&[esc, self.quote])?;
                    } else {
                        self.wtr.write_all(&[field[i]])?;
                    }
                    i += 1;
                }
            } else {
                let mut last = 0;
                for i in 0..field.len() {
                    if field[i] == self.quote {
                        self.wtr.write_all(&field[last..i])?;
                        self.wtr.write_all(&[self.quote, self.quote])?;
                        last = i + 1;
                    }
                }
                self.wtr.write_all(&field[last..])?;
            }
        } else {
            self.wtr.write_all(field)?;
        }
        if needs {
            self.wtr.write_all(&[self.quote])?;
        }
        Ok(())
    }

    pub fn write(&mut self, record: &[Vec<u8>]) -> io::Result<()> {
        let single = record.len() == 1;
        for (i, field) in record.iter().enumerate() {
            if i > 0 {
                self.wtr.write_all(&[self.delimiter])?;
            }
            let force = single && field.is_empty();
            self.write_field(field, force)?;
        }
        self.wtr.write_all(&self.term)?;
        Ok(())
    }

    pub fn write_field_seq(&mut self, fields: &[&[u8]]) -> io::Result<()> {
        self.write(&fields.iter().map(|f| f.to_vec()).collect::<Vec<_>>())
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.wtr.flush()
    }
}
RSEOF
echo done"}

