//! Command line argument parsing.  This mimics the behaviour (including the
//! error messages) of the docopt based parser used by the original program.
use std::collections::HashMap;

pub struct Flag {
    pub short: Option<char>,
    pub long: &'static str,
    pub arg: bool,
}

pub struct Spec {
    pub flags: &'static [Flag],
    /// minimum and maximum number of positional arguments
    pub min_pos: usize,
    pub max_pos: usize,
    /// positional argument names, used for error messages
    pub pos_names: &'static [&'static str],
    /// subcommands (used by `cat`); the first positional must be one of these
    pub subs: &'static [&'static str],
}

pub const fn f(short: Option<char>, long: &'static str, arg: bool) -> Flag {
    Flag { short, long, arg }
}

#[derive(Default)]
pub struct Parsed {
    pub vals: HashMap<String, String>,
    pub pos: Vec<String>,
}

impl Parsed {
    pub fn has(&self, long: &str) -> bool {
        self.vals.contains_key(long)
    }
    pub fn get(&self, long: &str) -> Option<&str> {
        self.vals.get(long).map(|s| s.as_str())
    }
    pub fn str_or(&self, long: &str, dflt: &str) -> String {
        match self.vals.get(long) {
            Some(s) => s.clone(),
            None => dflt.to_string(),
        }
    }
    pub fn num(&self, long: &str) -> Option<u64> {
        self.vals.get(long).and_then(|s| s.parse::<u64>().ok())
    }
}

/// Format an error message together with the usage section of a command.
pub fn usage_err(usage: &str, msg: &str) -> String {
    format!("{}\n\n{}", msg, usage.trim_end())
}

fn lookup_long<'a>(spec: &'a Spec, name: &str) -> Option<&'a Flag> {
    spec.flags.iter().find(|f| f.long == name)
}
fn lookup_short<'a>(spec: &'a Spec, c: char) -> Option<&'a Flag> {
    spec.flags.iter().find(|f| f.short == Some(c))
}

/// Parse the arguments according to `spec`.  `args` are the arguments after the
/// command name.  `usage` is the "Usage:" section used for error messages.
pub fn parse(spec: &Spec, usage: &str, args: &[String]) -> Result<Parsed, String> {
    let mut p = Parsed::default();
    let mut i = 0;
    let mut positional_only = false;
    while i < args.len() {
        let a = &args[i];
        if !positional_only && a == "--" {
            positional_only = true;
            i += 1;
            continue;
        }
        if !positional_only && a.starts_with("--") {
            let body = &a[2..];
            let (name, inline) = match body.find('=') {
                Some(k) => (&body[..k], Some(body[k + 1..].to_string())),
                None => (body, None),
            };
            let flag = match lookup_long(spec, name) {
                Some(f) => f,
                None => return Err(usage_err(usage, &format!("Unknown flag: '{}'", a))),
            };
            if flag.arg {
                let val = match inline {
                    Some(v) => v,
                    None => {
                        i += 1;
                        if i >= args.len() {
                            return Err(usage_err(usage, &format!("Expected argument for flag '--{}' but reached end of arguments.", flag.long)));
                        }
                        args[i].clone()
                    }
                };
                p.vals.insert(flag.long.to_string(), val);
            } else {
                p.vals.insert(flag.long.to_string(), String::new());
            }
            i += 1;
            continue;
        }
        if !positional_only && a.len() > 1 && a.starts_with('-') {
            let chars: Vec<char> = a.chars().collect();
            let mut j = 1;
            while j < chars.len() {
                let c = chars[j];
                let flag = match lookup_short(spec, c) {
                    Some(f) => f,
                    None => {
                        return Err(usage_err(usage, &format!("Unknown flag: '-{}'", c)));
                    }
                };
                if flag.arg {
                    let rest: String = chars[j + 1..].iter().collect();
                    let val = if !rest.is_empty() {
                        rest
                    } else {
                        i += 1;
                        if i >= args.len() {
                            return Err(usage_err(usage, &format!("Expected argument for flag '--{}' but reached end of arguments.", flag.long)));
                        }
                        args[i].clone()
                    };
                    p.vals.insert(flag.long.to_string(), val);
                    j = chars.len();
                    break;
                } else {
                    p.vals.insert(flag.long.to_string(), String::new());
                    j += 1;
                }
            }
            i += 1;
            continue;
        }
        p.pos.push(a.clone());
        i += 1;
    }
    if !spec.subs.is_empty() {
        if p.pos.is_empty() || !spec.subs.contains(&p.pos[0].as_str()) {
            return Err(usage_err(usage, "Invalid arguments."));
        }
    }
    if p.pos.len() < spec.min_pos || p.pos.len() > spec.max_pos {
        return Err(usage_err(usage, "Invalid arguments."));
    }
    Ok(p)
}

/// Parse a u64 argument, producing the same error message as the original.
pub fn u64_arg(val: &str, name: &str) -> Result<u64, String> {
    match val.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(_) => Err(format!("Could not deserialize '{}' to u64 for '{}'.", val, name)),
    }
}
RSEOF
