{"command": "cat > src/util.rs <<'RSEOF'
//! Shared helpers: reading inputs, writing output, parsing single-character
//! arguments.
use crate::csv::{Reader, Writer};
use std::fs;
use std::io::{self, Read, Write};

pub const STDIN: &str = "<stdin>";

/// Open a file for reading, or stdin when the path is empty.
pub fn input(path: Option<&str>) -> io::Result<Box<dyn io::Read + Send>> {
    match path {
        None | Some("-") | Some("") => Ok(Box::new(io::stdin())),
        Some(p) => match fs::File::open(p) {
            Ok(f) => Ok(Box::new(f)),
            Err(e) => Err(io::Error::new(e.kind(), format!("failed to open {}: {}", p, e))),
        },
    }
}

pub fn input_or_stdin(path: Option<&str>) -> io::Result<Box<dyn io::Read + Send>> {
    match path {
        None | Some("-") | Some("") => Ok(Box::new(io::stdin())),
        Some(p) => match fs::File::open(p) {
            Ok(f) => Ok(Box::new(f)),
            Err(e) => Err(io::Error::new(e.kind(), format!("failed to open {}: {}", p, e))),
        },
    }
}

/// The `-o/--output` target.  Returns None when writing to stdout.
pub fn output(path: Option<&str>) -> io::Result<Box<dyn io::Write + Send>> {
    match path {
        None | Some("-") | Some("") => Ok(Box::new(io::stdout())),
        Some(p) => match fs::File::create(p) {
            Ok(f) => Ok(Box::new(f)),
            Err(e) => Err(io::Error::new(e.kind(), format!("failed to open {}: {}", p, e))),
        },
    }
}

/// Convert a command line argument to a single ASCII byte, expanding `\t`.
pub fn single_arg(arg: &str) -> Result<u8, String> {
    if arg == "\\t" {
        return Ok(b'\t');
    }
    let b = arg.as_bytes();
    if b.len() != 1 || b[0] >= 0x80 {
        return Err(format!("Could not convert '{}' to a single ASCII character.", arg));
    }
    let c = b[0];
    if c == b'\n' || c == b'\r' || c == 0 {
        return Err(format!("Could not convert '{}' to a single ASCII character.", arg));
    }
    Ok(c)
}

pub fn delimiter_arg(arg: &str) -> Result<u8, String> {
    single_arg(arg)
}

/// Build a reader with the common options applied.
pub struct RdrCfg {
    pub delimiter: u8,
    pub quote: Option<u8>,
    pub escape: Option<u8>,
    pub no_quoting: bool,
}

pub fn make_reader<R: io::Read>(rdr: R, cfg: &RdrCfg) -> Reader<R> {
    let mut r = Reader::new(rdr);
    r.delimiter = cfg.delimiter;
    if let Some(q) = cfg.quote {
        r.quote = q;
    }
    r.escape = cfg.escape;
    r.quoting = !cfg.no_quoting;
    r
}

/// Build a writer with the common options applied.
pub struct WtrCfg {
    pub delimiter: u8,
    pub quote: Option<u8>,
    pub escape: Option<u8>,
    pub quote_always: bool,
    pub term: Vec<u8>,
}

pub fn make_writer<W: io::Write>(wtr: W, cfg: &WtrCfg) -> Writer<W> {
    let mut w = Writer::new(wtr);
    w.delimiter = cfg.delimiter;
    if let Some(q) = cfg.quote {
        w.quote = q;
    }
    w.escape = cfg.escape;
    if cfg.quote_always {
        w.quoting = false; // placeholder, replaced below
        w.quoting = true;
        w.quote_always_flag = true;
    }
    w.term = cfg.term.clone();
    w
}

/// Read all records (as byte records) from a reader.
pub fn read_all<R: io::Read>(r: &mut Reader<R>) -> crate::csv::CsvResult<Vec<Vec<Vec<u8>>>> {
    let mut out = Vec::new();
    let mut rec = Vec::new();
    while r.read(&mut rec)? {
        out.push(rec.clone());
    }
    Ok(out)
}

pub fn write_stdout(s: &str) {
    let out = io::stdout();
    let mut lock = out.lock();
    let _ = lock.write_all(s.as_bytes());
    let _ = lock.flush();
}
RSEOF
echo ok"}

