mod cli;
mod csv;
mod select;
mod usage;
mod util;

use cli::{Spec, f, Parsed};
use csv::{Reader, Writer};
use std::io::Write;

const VERSION: &str = "0.13.0";
const COMMANDS: &[(&str, &str)] = &[
    ("cat", "Concatenate by row or column"),
    ("count", "Count records"),
    ("fixlengths", "Makes all records have same length"),
    ("flatten", "Show one field per line"),
    ("fmt", "Format CSV output (change field delimiter)"),
    ("frequency", "Show frequency tables"),
    ("headers", "Show header names"),
    ("help", "Show this usage message."),
    ("index", "Create CSV index for faster access"),
    ("input", "Read CSV data with special quoting rules"),
    ("join", "Join CSV files"),
    ("partition", "Partition CSV data based on a column value"),
    ("sample", "Randomly sample CSV data"),
    ("reverse", "Reverse rows of CSV data"),
    ("search", "Search CSV data with regexes"),
    ("select", "Select columns from CSV"),
    ("slice", "Slice records from CSV"),
    ("sort", "Sort CSV data"),
    ("split", "Split CSV data into many files"),
    ("stats", "Compute basic statistics"),
    ("table", "Align CSV data into columns"),
];

fn usage_section(usage: &str) -> String {
    usage.trim_end().to_string()
}

type R = Result<(), String>;

fn err(usage: &str, msg: &str) -> String {
    cli::usage_err(usage, msg)
}

struct Common {
    no_headers: bool,
    delim: u8,
    out: Option<String>,
}

fn common(p: &Parsed, usage: &str, has_out: bool) -> Result<Common, String> {
    let delim = match p.get("delimiter") {
        Some(d) => util::delimiter_arg(d).map_err(|e| err(usage, &e))?,
        None => b',',
    };
    Ok(Common {
        no_headers: p.has("no-headers"),
        delim,
        out: if has_out { p.get("output").map(|s| s.to_string()) } else { None },
    })
}

fn open_rdr(path: Option<&str>, c: &Common) -> std::result::Result<Reader<Box<dyn std::io::Read + Send>>, String> {
    match util::input(path) {
        Ok(r) => {
            let mut r = Reader::new(r);
            r.delimiter = c.delim;
            Ok(r)
        }
        Err(e) => Err(e.to_string()),
    }
}

fn open_wtr(path: Option<&str>, c: &Common) -> std::result::Result<Writer<Box<dyn std::io::Write + Send>>, String> {
    match util::output(path) {
        Ok(w) => {
            let mut w = Writer::new(w);
            w.delimiter = c.delim;
            Ok(w)
        }
        Err(e) => Err(e.to_string()),
    }
}

fn read_headers<R: std::io::Read>(r: &mut Reader<R>) -> Result<Vec<Vec<u8>>, String> {
    let mut rec = Vec::new();
    match r.read(&mut rec) {
        Ok(true) => Ok(rec.clone()),
        Ok(false) => Ok(Vec::new()),
        Err(e) => Err(e.to_string()),
    }
}

// ---------------------------------------------------------------- commands

fn cmd_count(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv count [options] [<input>]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 0, max_pos: 1, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::COUNT); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, false)?;
    let mut r = open_rdr(p.pos.get(0).map(|s| s.as_str()), &c)?;
    let mut n: u64 = 0;
    if !c.no_headers {
        let mut rec = Vec::new();
        let _ = r.read(&mut rec);
    }
    let mut rec = Vec::new();
    while r.read(&mut rec).map_err(|e| e.to_string())? {
