fn common(p: &Parsed, usage: &str, has_out: bool) -> Result<Common, String> {
    let delim = match p.get("delimiter") {
        Some(d) => util::delimiter_arg(d).map_err(|e| err(usage, &e))?,
        None => b',',
    };
    Ok(Common {
        no_headers: p.has("no-headers"),
        delim,
        out: if has_out { p.get("output").map(|s| s.to_string()) } else { None },
    })
}

fn open_rdr(path: Option<&str>, c: &Common) -> std::result::Result<Reader<Box<dyn std::io::Read + Send>>, String> {
    match util::input(path) {
        Ok(r) => {
            let mut r = Reader::new(r);
            r.delimiter = c.delim;
            Ok(r)
        }
        Err(e) => Err(e.to_string()),
    }
}

fn open_wtr(path: Option<&str>, c: &Common) -> std::result::Result<Writer<Box<dyn std::io::Write + Send>>, String> {
    match util::output(path) {
        Ok(w) => {
            let mut w = Writer::new(w);
            w.delimiter = c.delim;
            Ok(w)
        }
        Err(e) => Err(e.to_string()),
    }
}

fn read_headers<R: std::io::Read>(r: &mut Reader<R>) -> Result<Vec<Vec<u8>>, String> {
    let mut rec = Vec::new();
    match r.read(&mut rec) {
        Ok(true) => Ok(rec.clone()),
        Ok(false) => Ok(Vec::new()),
        Err(e) => Err(e.to_string()),
    }
}

// ---------------------------------------------------------------- commands

fn cmd_count(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv count [options] [<input>]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 0, max_pos: 1, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::COUNT); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, false)?;
    let mut r = open_rdr(p.pos.get(0).map(|s| s.as_str()), &c)?;
    let mut n: u64 = 0;
    if !c.no_headers {
        let mut rec = Vec::new();
        let _ = r.read(&mut rec);
    }
    let mut rec = Vec::new();
    while r.read(&mut rec).map_err(|e| e.to_string())? {
        n += 1;
    }
    util::write_stdout(&format!("{}\n", n));
    Ok(())
}

fn cmd_headers(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv headers [options] [<input>...]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('j'), "just-names", false), f(None, "intersect", false), f(Some('d'), "delimiter", true)],
        min_pos: 0, max_pos: usize::MAX, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::HEADERS); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, false)?;
    let inputs = if p.pos.is_empty() { vec![String::new()] } else { p.pos.clone() };
    let just_names = p.has("just-names") || inputs.len() > 1;
    let intersect = p.has("intersect");
    let mut out = String::new();
    let mut seen: Vec<Vec<u8>> = Vec::new();
    for (i, input) in inputs.iter().enumerate() {
        let mut r = open_rdr(Some(input), &c)?;
        let hs = read_headers(&mut r)?;
        if intersect {
            if i == 0 {
                seen = hs.clone();
            } else {
                for h in hs.iter() {
                    if !seen.contains(h) { seen.push(h.clone()); }
                }
            }
            continue;
        }
        if just_names {
            for h in hs.iter() { out.push_str(&String::from_utf8_lossy(h)); out.push('\n'); }
        } else {
            for (k, h) in hs.iter().enumerate() {
                out.push_str(&format!("{}   {}\n", k + 1, String::from_utf8_lossy(h)));
            }
        }
    }
    if intersect {
        if just_names || inputs.len() > 1 {
            for h in seen.iter() { out.push_str(&String::from_utf8_lossy(h)); out.push('\n'); }
        } else {
            for (k, h) in seen.iter().enumerate() {
                out.push_str(&format!("{}   {}\n", k + 1, String::from_utf8_lossy(h)));
            }
        }
    }
    util::write_stdout(&out);
    Ok(())
}

fn cmd_cat(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('p'), "pad", false), f(Some('o'), "output", true), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 1, max_pos: usize::MAX, pos_names: &["input"], subs: &["rows", "columns"],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::CAT); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, true)?;
    let mut w = open_wtr(c.out.as_deref(), &c)?;
    let inputs: Vec<String> = p.pos[1..].to_vec();
    if inputs.is_empty() { let _ = w.flush(); return Ok(()); }
    let mode = p.pos[0].clone();
    if mode == "rows" {
        let mut first = true;
        let mut expected: Option<usize> = None;
        for (i, input) in inputs.iter().enumerate() {
            let mut r = open_rdr(Some(input), &c)?;
            let mut rec = Vec::new();
            if i == 0 && !c.no_headers {
                match r.read(&mut rec) {
                    Ok(true) => { expected = Some(rec.len()); w.write(&rec).map_err(|e| e.to_string())?; }
                    Ok(false) => {}
                    Err(e) => return Err(e.to_string()),
                }
                first = false;
            }
            loop {
                match r.read(&mut rec) {
                    Ok(true) => {
                        w.write(&rec).map_err(|e| e.to_string())?;
                        if let Some(e) = expected { if e != rec.len() { return Err("CSV error: found record with X fields".to_string()); } }
                    }
                    Ok(false) => break,
                    Err(e) => return Err(e.to_string()),
                }
            }
            let _ = first;
        }
    } else {
        // columns
        let mut readers = Vec::new();
        let mut headers: Vec<Vec<u8>> = Vec::new();
        let mut rows: Vec<Vec<Vec<Vec<u8>>>> = Vec::new();
        for input in inputs.iter() {
            let mut r = open_rdr(Some(input), &c)?;
            let hs = read_headers(&mut r)?;
            let mut data = Vec::new();
            let mut rec = Vec::new();
            while r.read(&mut rec).map_err(|e| e.to_string())? { data.push(rec.clone()); }
            readers.push((hs, data));
        }
        let mut ncols = 0;
        for (hs, _) in readers.iter() { ncols += hs.len(); }
        for (hs, _) in readers.iter() { for h in hs.iter() { headers.push(h.clone()); } }
        w.write(&headers).map_err(|e| e.to_string())?;
        let maxlen = readers.iter().map(|(_, d)| d.len()).max().unwrap_or(0);
        for i in 0..maxlen {
            let mut row: Vec<Vec<u8>> = Vec::new();
            let mut ok = true;
            for (_, d) in readers.iter() {
                if i < d.len() { for f in d[i].iter() { row.push(f.clone()); } } else { ok = false; }
            }
            if !ok && !p.has("pad") { break; }
            while row.len() < ncols { row.push(Vec::new()); }
            w.write(&row).map_err(|e| e.to_string())?;
        }
    }
    w.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn cmd_select(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('o'), "output", true), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 1, max_pos: 2, pos_names: &["selection", "input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::SELECT); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, true)?;
    let sel = &p.pos[0];
    let input = p.pos.get(1).map(|s| s.as_str());
    let mut r = open_rdr(input, &c)?;
    let mut w = open_wtr(c.out.as_deref(), &c)?;
    let hs = read_headers(&mut r)?;
    let s = select::Selector::parse(&hs, sel)?;
    let mut idx = s.select(&hs)?;
    if c.no_headers {
        // the first row is data; re-resolve against an empty header list
        idx = match (s.fields.is_empty(), s.negate) {
            (true, true) => Vec::new(),
            _ => Vec::new(),
        };
        return Err("Invalid arguments.".to_string());
    }
    let mut out_hs: Vec<Vec<u8>> = Vec::new();
    for i in idx.iter() { out_hs.push(hs[*i].clone()); }
    w.write(&out_hs).map_err(|e| e.to_string())?;
    let mut rec = Vec::new();
    while r.read(&mut rec).map_err(|e| e.to_string())? {
        let mut row: Vec<Vec<u8>> = Vec::new();
        for i in idx.iter() { row.push(rec[*i].clone()); }
        w.write(&row).map_err(|e| e.to_string())?;
    }
    w.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn cmd_slice(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv slice [options] [<input>]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('s'), "start", true), f(Some('e'), "end", true), f(Some('l'), "len", true), f(Some('i'), "index", true), f(Some('o'), "output", true), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 0, max_pos: 1, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") {
        util::write_stdout(usage::SLICE); return Ok(());
    }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, true)?;
    let gnum = |name: &str| -> Result<Option<u64>, String> {
        match p.get(name) {
            Some(v) => Ok(Some(cli::u64_arg(v, &format!("--{}", name)).map_err(|e| err(U, &e))?)),
            None => Ok(None),
        }
    };
    let start = gnum("start")?;
    let end = gnum("end")?;
    let len = gnum("len")?;
    let index = gnum("index")?;
    let (start, end) = match index {
        Some(i) => (i, Some(i + 1)),
        None => {
            let s = start.unwrap_or(0);
            let e = match (end, len) {
                (Some(e), _) => Some(e),
                (None, Some(l)) => Some(s + l),
                _ => None,
            };
            if let Some(e) = e { if e < s { return Err(err(U, &format!("The end of the range ({}) must be greater than or\nequal to the start of the range ({}).", e, s))); } }
            (s, e)
        }
    };
    let mut r = open_rdr(p.pos.get(0).map(|s| s.as_str()), &c)?;
    let mut w = open_wtr(c.out.as_deref(), &c)?;
    if !c.no_headers {
        let hs = read_headers(&mut r)?;
        w.write(&hs).map_err(|e| e.to_string())?;
    }
    let mut rec = Vec::new();
    let mut i: u64 = 0;
    while r.read(&mut rec).map_err(|e| e.to_string())? {
        if i >= start && end.map(|e| i < e).unwrap_or(true) {
            w.write(&rec).map_err(|e| e.to_string())?;
        }
        if let Some(e) = end { if i >= e { break; } }
        i += 1;
    }
    w.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn cmd_reverse(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv reverse [options] [<input>]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('o'), "output", true), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true)],
        min_pos: 0, max_pos: 1, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") { util::write_stdout(usage::REVERSE); return Ok(()); }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, true)?;
    let mut r = open_rdr(p.pos.get(0).map(|s| s.as_str()), &c)?;
    let mut w = open_wtr(c.out.as_deref(), &c)?;
    let mut hs: Option<Vec<Vec<u8>>> = None;
    if !c.no_headers { hs = Some(read_headers(&mut r)?); }
    let mut rows: Vec<Vec<Vec<u8>>> = Vec::new();
    let mut rec = Vec::new();
    while r.read(&mut rec).map_err(|e| e.to_string())? { rows.push(rec.clone()); }
    if let Some(h) = hs { w.write(&h).map_err(|e| e.to_string())?; }
    for row in rows.iter().rev() { w.write(row).map_err(|e| e.to_string())?; }
    w.flush().map_err(|e| e.to_string())?;
    Ok(())
}

fn cmd_sort(args: &[String]) -> R {
    const U: &str = "Usage:\n    xsv sort [options] [<input>]";
    let spec = Spec {
        flags: &[f(Some('h'), "help", false), f(Some('o'), "output", true), f(Some('n'), "no-headers", false), f(Some('d'), "delimiter", true), f(Some('s'), "select", true), f(Some('N'), "numeric", false), f(Some('R'), "reverse", false)],
        min_pos: 0, max_pos: 1, pos_names: &["input"], subs: &[],
    };
    if args.iter().any(|a| a == "-h" || a == "--help") { util::write_stdout(usage::SORT); return Ok(()); }
    let p = cli::parse(&spec, U, args).map_err(|e| e)?;
    let c = common(&p, U, true)?;
    let mut r = open_rdr(p.pos.get(0).map(|s| s.as_str()), &c)?;
    let mut w = open_wtr(c.out.as_deref(), &c)?;
    let hs = read_headers(&mut r)?;
    let mut rows: Vec<Vec<Vec<u8>>> = Vec::new();
    let mut rec = Vec::new();
    while r.read(&mut rec).map_err(|e| e.to_string())? { rows.push(rec.clone()); }
    // build key
    let mut key: Vec<Vec<u8>> = Vec::new();
    if let Some(sel) = p.get("select") {
        let s = select::Selector::parse(&hs, sel).map_err(|e| err(U, &e))?;
        let idx = s.select(&hs).map_err(|e| err(U, &e))?;
        for row in rows.iter() {
            let mut k = Vec::new();
            for i in idx.iter() { k.extend_from_slice(&row[*i]); k.push(b'\x01'); }
            key.push(k);
        }
    } else {
        for row in rows.iter() {
            let mut k = Vec::new();
            for f in row.iter() { k.extend_from_slice(f); k.push(b'\x01'); }
            key.push(k);
        }
    }
    let numeric = p.has("numeric");
    let rev = p.has("reverse");
    let mut order: Vec<usize> = (0..rows.len()).collect();
    order.sort_by(|&a, &b| {
        let ka = &key[a];
        let kb = &key[b];
        let o = if numeric {
            let (x, y) = (num_prefix(ka), num_prefix(kb));
            match (x, y) {
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal),
                (Some(_), None) => std::cmp::Ordering::Greater,
                (None, Some(_)) => std::cmp::Ordering::Less,
                _ => std::cmp::Ordering::Equal,
            }
        } else { ka.cmp(kb) };
        if rev { o.reverse() } else { o }
    });
    w.write(&hs).map_err(|e| e.to_string())?;
    for i in order.iter() { w.write(&rows[*i]).map_err(|e| e.to_string())?; }
    w.flush().map_err(|e| e.to_string())?;
    Ok(())
}

/// Parse the leading numeric part of a byte string.
fn num_prefix(b: &[u8]) -> Option<f64> {
    let mut i = 0;
    let mut out = Vec::new();
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') { out.push(b[i]); i += 1; }
    let mut seen_digit = false;
    while i < b.len() && b[i].is_ascii_digit() { out.push(b[i]); i += 1; seen_digit = true; }
    if i < b.len() && b[i] == b'.' { out.push(b[i]); i += 1; }
    while i < b.len() && b[i].is_ascii_digit() { out.push(b[i]); i += 1; seen_digit = true; }
    if !seen_digit { return None; }
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        let mut j = i + 1;
        let mut exp = Vec::new();
        if j < b.len() && (b[j] == b'+' || b[j] == b'-') { exp.push(b[j]); j += 1; }
        let mut ed = false;
        while j < b.len() && b[j].is_ascii_digit() { exp.push(b[j]); j += 1; ed = true; }
        if ed { out.extend_from_slice(b[i..j].iter()); i = j; }
    }
    String::from_utf8_lossy(&out).parse::<f64>().ok()
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let code = run(&args);
    std::process::exit(code);
}

fn run(args: &[String]) -> i32 {
    if args.is_empty() {
        util::write_stdout(usage::INTRO);
        return 0;
    }
    if args[0] == "--" {
        if args.len() == 1 { util::write_stdout(usage::INTRO); return 0; }
        return report(&format!("xsv expects commands in lowercase. Did you mean '--'?"));
    }
    if args[0].starts_with('-') {
        for a in args {
            match a.as_str() {
                "--version" => { util::write_stdout(&format!("{}\n", VERSION)); return 0; }
                "--list" => {}
                "-h" | "--help" => { util::write_stdout(usage::MAIN); return 0; }
                _ => return report(&cli::usage_err(&usage_section(usage::MAIN), &format!("Unknown flag: '{}'", a))),
            }
        }
        util::write_stdout(usage::LIST);
        return 0;
    }
    let cmd = &args[0];
    let rest = &args[1..];
    match cmd.as_str() {
        "cat" => dispatch(cmd_cat, rest),
        "count" => dispatch(cmd_count, rest),
        "headers" => dispatch(cmd_headers, rest),
        "select" => dispatch(cmd_select, rest),
        "slice" => dispatch(cmd_slice, rest),
        "reverse" => dispatch(cmd_reverse, rest),
        "sort" => dispatch(cmd_sort, rest),
        "help" => { util::write_stdout(&format!("\n{}", usage::MAIN)); 0 }
        _ => {
            if let Some(m) = COMMANDS.iter().find(|(n, _)| n.to_lowercase() == cmd.to_lowercase()) {
                report(&format!("xsv expects commands in lowercase. Did you mean '{}'?", m.0))
            } else {
                let list: Vec<String> = COMMANDS.iter().map(|(n, _)| format!("\"{}\"", n)).collect();
                report(&format!("Could not match '{}' with any of the allowed variants: [{}]", cmd, list.join(", ")))
            }
        }
    }
}

fn dispatch<F: Fn(&[String]) -> Result<(), String>>(f: F, args: &[String]) -> i32 {
    match f(args) {
        Ok(()) => 0,
        Err(e) => report(&e),
    }
}

fn report(msg: &str) -> i32 {
    let errw = std::io::stderr();
    let mut l = errw.lock();
    let _ = writeln!(l, "{}", msg);
    let _ = l.flush();
    1
}
